fields.InputDefinition:
{
  "goal": "In the Component Studio app (Components section), click the 'New Component' button. Verify the 'Create New Component' dialog opens showing a Name field (marked required), a Type selection rendered as a card grid, a Title field, and a Description textarea. Confirm the 'Create' button is DISABLED while Name is empty, then type a name and verify 'Create' becomes enabled. Pages can take 10-30s to load — wait, don't navigate away. Seeing the dialog render with its fields and the Create button gating on the required Name is success — you do NOT need to actually create the component (you may Cancel).",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 35,
  "judgeValidationCriteria": [
    "Clicking 'New Component' opens a 'Create New Component' dialog with a required Name field, a Type card grid, Title, and Description",
    "The 'Create' button is disabled with an empty Name and becomes enabled after a name is entered",
    "No error messages, blank screens, or crash pages"
  ]
}
